| `mesh.thinInstanceSetBuffer("color", data, 4)` | `setThinInstanceColors(mesh, data)` |
| `new Vector3(x, y, z)` | `{ x, y, z }` or `[x, y, z]` |
| `new Color3(r, g, b)` | `[r, g, b]` |
| `Matrix.Identity()` | `mat4Identity()` |
| `mesh.dispose()` | `removeFromScene(scene, mesh)` |
| `scene.onBeforeRenderObservable.add(fn)` | `onBeforeRender(scene, fn)` |

---

## Key Differences

### 1. No Scene in Constructors

BJS objects take `scene` in their constructor and auto-register. Lite objects are plain data — you create them, then `addToScene()` them explicitly.

```typescript
// ❌ Babylon.js
const light = new HemisphericLight("light", new Vector3(0, 1, 0), scene);

// ✅ Babylon Lite
const light = createHemisphericLight([0, 1, 0], 1.0);
addToScene(scene, light);
```

### 2. Engine & Render Loop

BJS uses `runRenderLoop` with a callback. Lite uses a single `startEngine(engine)` that returns a promise resolving after the first frame.

```typescript
// ❌ Babylon.js
const engine = new WebGPUEngine(canvas);
await engine.initAsync();
const scene = new Scene(engine);
// ... setup ...
engine.runRenderLoop(() => scene.render());

// ✅ Babylon Lite
const engine = await createEngine(canvas);
const scene = createSceneContext(engine);
// ... setup ...
await startEngine(engine);
```

### 3. Plain Data, Not Classes

Lite uses plain objects, arrays, and `Float32Array` instead of BJS classes like `Vector3`, `Color3`, `Matrix`.

```typescript
// ❌ Babylon.js
light.direction = new Vector3(0, -1, 0);
light.diffuse = new Color3(1, 0, 0);

// ✅ Babylon Lite
const light = createDirectionalLight([0, -1, 0]);
light.diffuse = [1, 0, 0];
```

### 4. Camera Controls Are Separate

BJS cameras have `attachControl` as a method. Lite separates camera data from input handling.

```typescript
// ❌ Babylon.js
const camera = new ArcRotateCamera("cam", -Math.PI/2, Math.PI/2, 5, Vector3.Zero(), scene);
camera.attachControl(canvas, true);

// ✅ Babylon Lite
const camera = createArcRotateCamera(-Math.PI/2, Math.PI/2, 5, { x: 0, y: 0, z: 0 });
scene.camera = camera;
attachControl(camera, canvas, scene);
```

### 5. Loaders and Scene Registration

`loadEnvironment()` adds its environment data/renderables to the scene internally. `loadGltf()` returns an asset container; pass it to `addToScene()` so transform-node hierarchies, meshes, and animation groups are registered explicitly.

```typescript
// ❌ Babylon.js
await SceneLoader.ImportMeshAsync("", baseUrl, "model.glb", scene);
scene.environmentTexture = new CubeTexture(envUrl, scene);
scene.createDefaultEnvironment({ createSkybox: true, skyboxSize: 1000 });

// ✅ Babylon Lite
addToScene(scene, await loadGltf(engine, "model.glb"));

// Scene 18: Spotlight Hard Shadows (PCF) — FreeCamera + SpotLight + PCF Shadow Generator
// Demonstrates new FreeCamera type and PCF shadow mapping for spot lights.

import { addToScene, startEngine, createEngine, createSceneContext, createFreeCamera, createSpotLight, createGround, createBox, createStandardMaterial, createPcfSpotlightShadowGenerator, setShadowTaskCasterMeshes, loadTexture2D, attachFreeControl, registerSceneWithShadowSupport } from "babylon-lite";

async function main(): Promise<void> {
    const __initStart = performance.now();
    const canvas = document.getElementById("renderCanvas") as HTMLCanvasElement;
    const engine = await createEngine(canvas);
    const scene = createSceneContext(engine);

    // FreeCamera at (0, 10, -20) looking at origin
    const cam = createFreeCamera({ x: 0, y: 10, z: -20 }, { x: 0, y: 0, z: 0 });
    cam.nearPlane = 1;
    cam.farPlane = 10000;
    scene.camera = cam;
    attachFreeControl(cam, canvas, scene);

    // Ground — 24×60 with diffuse texture, emissive glow, no specular
    const ground = createGround(engine, { width: 24, height: 60 });
    const groundMat = createStandardMaterial();
    groundMat.diffuseTexture = await loadTexture2D(engine, "https://playground.babylonjs.com/textures/ground.jpg");
    groundMat.specularColor = [0, 0, 0];
    groundMat.emissiveColor = [0.2, 0.2, 0.2];
    ground.material = groundMat;
    ground.receiveShadows = true;
    addToScene(scene, ground);

    // Box — size 5 at (0, 5, 0), red diffuse, dark red specular
    const box = createBox(engine, 5);
    box.position.set(0, 5, 0);
    const boxMat = createStandardMaterial();
    boxMat.diffuseColor = [1.0, 0, 0];
    boxMat.specularColor = [0.5, 0, 0];
    box.material = boxMat;
    addToScene(scene, box);

    // SpotLight at (0, 20, -10) pointing (0, -1, 0.3), angle=1.2, exponent=24
    const light = createSpotLight([0, 20, -10], [0, -1, 0.3], 1.2, 24);
    addToScene(scene, light);

    // PCF Shadow Generator — box casts shadow onto ground
    light.shadowGenerator = createPcfSpotlightShadowGenerator(engine, light, {
        mapSize: 512,
        near: cam.nearPlane,
        far: cam.farPlane,
    });
    setShadowTaskCasterMeshes(light.shadowGenerator, [box]);

    await registerSceneWithShadowSupport(scene);
    await startEngine(engine);
    canvas.dataset.drawCalls = String(engine.drawCallCount);
    canvas.dataset.initMs = String(performance.now() - __initStart);
    canvas.dataset.ready = "true";
}

main().catch(console.error);

