    return Object.fromEntries([
        ["main", resolve(__dirname, "index.html")],
        ...readdirSync(__dirname)
            .filter((f) => f.endsWith(".html") && f !== "index.html" && hasBuildableRootScripts(f))
            .map((f) => [f.replace(".html", ""), resolve(__dirname, f)]),
        ...liteHtml,
    ]);
}

