// FPS terrain — destructible ground for the Quake-style demo (scene252).
//
// A dense grid over a 128×128u arena, displaced by seeded low-frequency value noise
// (amplitude ~5u), with one static box collider per 4×4u tile. Destroying a tile
// removes its 6 indices from the mesh (index surgery + normal recompute + in-place
// GPU re-upload via resizeMeshGeometry), removes the tile's physics body, and adds a
// navmesh obstacle so bots route around the hole.

import {
    addBoxObstacle,
    computeNormals,
    createFlatGroundData,
    createMeshFromData,
    createPhysicsBody,
    createPhysicsShape,
    createTransformNode,
    removePhysicsBody,
    resizeMeshGeometry,
    setPhysicsBodyShape,
    setPhysicsShapeFilterMembershipMask,
    setPhysicsShapeMaterial,
    PhysicsMotionType,
    PhysicsShapeType,
} from "babylon-lite";
import type { EngineContext, Mesh, NavigationPlugin, ObstacleHandle, PhysicsBody, PhysicsWorld } from "babylon-lite";

/** Arena side length in metres. */
export const ARENA_SIZE = 128;
/** Tile footprint in metres (square). */
export const TILE_SIZE = 4;
/** Tiles per axis. */
export const TILE_COUNT = ARENA_SIZE / TILE_SIZE;
/** Noise amplitude in metres — gentle enough to keep flat-topped tile boxes close to the mesh. */
export const NOISE_AMPLITUDE = 5;
/** Collision layer bit for terrain tile boxes (used by bullet raycasts). */
export const TERRAIN_LAYER = 1;

/** One destructible tile of the arena. */
export interface FpsTile {
    /** Tile column (0..TILE_COUNT-1), X axis. */
    tx: number;
    /** Tile row (0..TILE_COUNT-1), Z axis. */
    tz: number;
    /** Whether the tile still exists. */
    alive: boolean;
    /** Static box collider, or null once destroyed. */
    body: PhysicsBody | null;
    /** Navmesh obstacle marking the hole, or null. */
    obstacle: ObstacleHandle | null;
}

/** The terrain mesh plus its tile grid. */
export interface FpsTerrain {
    /** The single dense grid mesh (re-uploaded in place on destruction). */
    mesh: Mesh;
    /** Tiles indexed tz * TILE_COUNT + tx. */
    tiles: FpsTile[];
    /** Number of tiles destroyed so far. */
    destroyedCount: number;
    /** @internal Coarse noise grid for heightAt. */
    _noiseGrid: Float32Array;
}

// ─── Seeded value noise ──────────────────────────────────────────────

const NOISE_CELLS = 8; // coarse cells per axis — low frequency, long undulations

/** Mulberry32 — small seeded PRNG, allocation-free per call. */
function makeRng(seed: number): () => number {
    let a = seed >>> 0;
    return () => {
        a = (a + 0x6d2b79f5) >>> 0;
        let t = a;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

function smoothstep(t: number): number {
    return t * t * (3 - 2 * t);
}

/** Bilinear value noise over the coarse grid, scaled to ±NOISE_AMPLITUDE. */
function noiseHeight(x: number, z: number, grid: Float32Array): number {
    const u = ((x + ARENA_SIZE / 2) / ARENA_SIZE) * NOISE_CELLS;
    const v = ((z + ARENA_SIZE / 2) / ARENA_SIZE) * NOISE_CELLS;
    const u0 = Math.min(Math.floor(u), NOISE_CELLS - 1);
    const v0 = Math.min(Math.floor(v), NOISE_CELLS - 1);
    const su = smoothstep(u - u0);
    const sv = smoothstep(v - v0);
    const n = NOISE_CELLS + 1;
    const a = grid[v0 * n + u0]! * (1 - su) + grid[v0 * n + u0 + 1]! * su;
    const b = grid[(v0 + 1) * n + u0]! * (1 - su) + grid[(v0 + 1) * n + u0 + 1]! * su;
    return (a * (1 - sv) + b * sv) * NOISE_AMPLITUDE;
}

/** Ground height at a world (x, z) point — for spawning and bot logic. */
export function terrainHeightAt(terrain: FpsTerrain, x: number, z: number): number {
    return noiseHeight(x, z, terrain._noiseGrid);
}

// ─── Construction ────────────────────────────────────────────────────

/**
 * Build the FPS terrain: one dense grid mesh plus a static box collider per tile.
 * The caller adds `terrain.mesh` to the scene.
 */
export function createFpsTerrain(engine: EngineContext, world: PhysicsWorld, seed = 1337): FpsTerrain {
    const rng = makeRng(seed);
    const grid = new Float32Array((NOISE_CELLS + 1) * (NOISE_CELLS + 1));
    for (let i = 0; i < grid.length; i++) {
        grid[i] = rng() * 2 - 1;
    }

    const ground = createFlatGroundData({ width: ARENA_SIZE, height: ARENA_SIZE, subdivisions: TILE_COUNT });
    const cols = TILE_COUNT + 1;
    for (let row = 0; row < cols; row++) {
        for (let col = 0; col < cols; col++) {
            const i = (row * cols + col) * 3;
            ground.positions[i + 1] = noiseHeight(ground.positions[i]!, ground.positions[i + 2]!, grid);
        }
    }
    const normals = computeNormals(ground.positions, ground.indices);
    const mesh = createMeshFromData(engine, "fpsTerrain", ground.positions, normals, ground.indices, ground.uvs);

    const tiles: FpsTile[] = [];
    for (let tz = 0; tz < TILE_COUNT; tz++) {
        for (let tx = 0; tx < TILE_COUNT; tx++) {
            // Corner heights of this tile (4 grid vertices).
            let yTop = -Infinity;
            let yBottom = Infinity;
            for (let dr = 0; dr <= 1; dr++) {
                for (let dc = 0; dc <= 1; dc++) {
                    const y = ground.positions[((tz + dr) * cols + (tx + dc)) * 3 + 1]!;
                    if (y > yTop) {
                        yTop = y;
                    }
                    if (y < yBottom) {
                        yBottom = y;
                    }
                }
            }
            const cx = -ARENA_SIZE / 2 + tx * TILE_SIZE + TILE_SIZE / 2;
            const cz = -ARENA_SIZE / 2 + tz * TILE_SIZE + TILE_SIZE / 2;
            // Box top sits at the tile's highest corner so characters never fall through;
            // a minimum half-height keeps the box non-degenerate on flat tiles.
            const halfH = Math.max((yTop - yBottom) / 2, 0.5);
            const node = createTransformNode("fpsTile", cx, yTop - halfH, cz);
            const body = createPhysicsBody(world, node, PhysicsMotionType.STATIC);
            const shape = createPhysicsShape(world, {
                type: PhysicsShapeType.BOX,
                parameters: { extents: { x: TILE_SIZE / 2, y: halfH, z: TILE_SIZE / 2 } },
            });
            setPhysicsBodyShape(world, body, shape);
            // Low friction for Quake-style ground slide; no bounce.
            setPhysicsShapeMaterial(world, shape, 0.1, 0);
            setPhysicsShapeFilterMembershipMask(world, shape, TERRAIN_LAYER);
            tiles.push({ tx, tz, alive: true, body, obstacle: null });
        }
    }

    return { mesh, tiles, destroyedCount: 0, _noiseGrid: grid };
}

/** Look up the tile containing a world (x, z) point, or null outside the arena. */
export function tileFromPoint(x: number, z: number): FpsTile | null {
    const tx = Math.floor((x + ARENA_SIZE / 2) / TILE_SIZE);
    const tz = Math.floor((z + ARENA_SIZE / 2) / TILE_SIZE);
    if (tx < 0 || tx >= TILE_COUNT || tz < 0 || tz >= TILE_COUNT) {
        return null;
    }
    return null; // placeholder replaced below
}

/**
 * Destroy one tile: drop its 6 indices from the grid mesh, recompute normals, re-upload
 * in place, remove its static body, and mark the hole on the navmesh.
 */
export function destroyTerrainTile(terrain: FpsTerrain, engine: EngineContext, world: PhysicsWorld, nav: NavigationPlugin | null, tile: FpsTile): void {
    if (!tile.alive) {
        return;
    }
    tile.alive = false;
    terrain.destroyedCount++;

    const mesh = terrain.mesh;
    const m = mesh as unknown as { _cpuIndices?: Uint32Array; _cpuPositions?: Float32Array; _cpuUvs?: Float32Array };
    const old = m._cpuIndices;
    if (!old) {
        return;
    }
    const start = (tile.tz * TILE_COUNT + tile.tx) * 6;
    const next = new Uint32Array(old.length - 6);
    next.set(old.subarray(0, start), 0);
    next.set(old.subarray(start + 6), start);
    const normals = computeNormals(m._cpuPositions!, next);
    resizeMeshGeometry(engine, mesh, m._cpuPositions!, normals, next, m._cpuUvs);

    if (tile.body) {
        removePhysicsBody(world, tile.body);
        tile.body = null;
    }
    if (nav) {
        tile.obstacle = addBoxObstacle(nav, { x: -ARENA_SIZE / 2 + tile.tx * TILE_SIZE + TILE_SIZE / 2, y: 0, z: -ARENA_SIZE / 2 + tile.tz * TILE_SIZE + TILE_SIZE / 2 }, { x: TILE_SIZE / 2, y: 2, z: TILE_SIZE / 2 }, 0);
    }
}

