// DOM input for the FPS demo — pointer-lock mouse look + WASD/space keyboard state.
// Lite has no input module by design; the demo owns its DOM listeners.

export interface FpsInput {
    /** True while the pointer is locked to the canvas. */
    locked: boolean;
    /** Move keys (WASD / arrows). */
    forward: boolean;
    back: boolean;
    left: boolean;
    right: boolean;
    jump: boolean;
    /** Mouse-look delta accumulated since the last read; resets to zero on read. */
    consumeLookDelta(): { dx: number; dy: number };
    /** Subscribe to shot requests (mouse-down while locked). Returns a disposer. */
    onFire(cb: () => void): () => void;
    /** Subscribe to pointer-lock changes. Returns a disposer. */
    onLockChange(cb: (locked: boolean) => void): () => void;
    /** Remove all listeners. */
    dispose(): void;
}

export function createFpsInput(canvas: HTMLCanvasElement): FpsInput {
    const state = { forward: false, back: false, left: false, right: false, jump: false };
    let locked = false;
    let dx = 0;
    let dy = 0;
    const fireSubs: (() => void)[] = [];
    const lockSubs: ((locked: boolean) => void)[] = [];

    const setKey = (code: string, down: boolean): void => {
        switch (code) {
            case "KeyW":
            case "ArrowUp":
                state.forward = down;
                break;
            case "KeyS":
            case "ArrowDown":
                state.back = down;
                break;
            case "KeyA":
            case "ArrowLeft":
                state.left = down;
                break;
            case "KeyD":
            case "ArrowRight":
                state.right = down;
                break;
            case "Space":
                state.jump = down;
                break;
        }
    };

    const onKeyDown = (e: KeyboardEvent): void => {
        if (e.code === "Space") {
            e.preventDefault();
        }
        setKey(e.code, true);
    };
    const onKeyUp = (e: KeyboardEvent): void => {
        setKey(e.code, false);
    };
    const onMouseMove = (e: MouseEvent): void => {
        if (!locked) {
            return;
        }
        dx += e.movementX;
        dy += e.movementY;
    };
    const onMouseDown = (e: MouseEvent): void => {
        if (!locked) {
            // First click requests pointer lock instead of firing.
            void canvas.requestPointerLock().catch(() => undefined);
            return;
        }
        if (e.button === 0) {
            for (const cb of fireSubs) {
                cb();
            }
        }
    };
    const onLockChange = (): void => {
        locked = document.pointerLockElement === canvas;
        for (const cb of lockSubs) {
            cb(locked);
        }
    };

    canvas.addEventListener("mousedown", onMouseDown);
    document.addEventListener("mousemove", onMouseMove);
    document.addEventListener("pointerlockchange", onLockChange);
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("keyup", onKeyUp);

    return {
        get locked() {
            return locked;
        },
        get forward() {
            return state.forward;
        },
        get back() {
            return state.back;
        },
        get left() {
            return state.left;
        },
        get right() {
            return state.right;
        },
        get jump() {
            return state.jump;
        },
        consumeLookDelta(): { dx: number; dy: number } {
            const out = { dx, dy };
            dx = 0;
            dy = 0;
            return out;
        },
        onFire(cb: () => void): () => void {
            fireSubs.push(cb);
            return () => {
                const i = fireSubs.indexOf(cb);
                if (i >= 0) {
                    fireSubs.splice(i, 1);
                }
            };
        },
        onLockChange(cb: (locked: boolean) => void): () => void {
            lockSubs.push(cb);
            return () => {
                const i = lockSubs.indexOf(cb);
                if (i >= 0) {
                    lockSubs.splice(i, 1);
                }
            };
        },
        dispose(): void {
            canvas.removeEventListener("mousedown", onMouseDown);
            document.removeEventListener("mousemove", onMouseMove);
            document.removeEventListener("pointerlockchange", onLockChange);
            window.removeEventListener("keydown", onKeyDown);
            window.removeEventListener("keyup", onKeyUp);
        },
    };
}

// Web Audio SFX for the FPS demo. Lite has no audio by design, so sounds are
// synthesized on the DOM side with Web Audio. The AudioContext is created lazily
// on the first user gesture (browser autoplay policy) — no module-level side effects.

export interface FpsAudio {
    /** Call from a user gesture (e.g. pointer lock) to unlock audio. */
    unlock(): void;
    gunshot(): void;
    hit(): void;
    thud(): void;
    damage(): void;
}

export function createFpsAudio(): FpsAudio {
    let ctx: AudioContext | null = null;

    const ensure = (): AudioContext | null => {
        if (!ctx) {
            try {
                ctx = new AudioContext();
            } catch {
                return null;
            }
        }
        if (ctx.state === "suspended") {
            void ctx.resume();
        }
        return ctx;
    };

    const playNoise = (seconds: number, startFreq: number, endFreq: number, gain: number): void => {
        const c = ensure();
        if (!c) {
            return;
        }
        const t = c.currentTime;
        const buf = c.createBuffer(1, Math.max(1, Math.floor(c.sampleRate * seconds)), c.sampleRate);
        const data = buf.getChannelData(0);
        for (let i = 0; i < data.length; i++) {
            data[i] = Math.random() * 2 - 1;
        }
        const src = c.createBufferSource();
        src.buffer = buf;
        const filter = c.createBiquadFilter();
        filter.type = "lowpass";
        filter.frequency.setValueAtTime(startFreq, t);
        filter.frequency.exponentialRampToValueAtTime(Math.max(40, endFreq), t + seconds);
        const g = c.createGain();
        g.gain.setValueAtTime(gain, t);
        g.gain.exponentialRampToValueAtTime(0.001, t + seconds);
        src.connect(filter);
        filter.connect(g);
        g.connect(c.destination);
        src.start(t);
        src.stop(t + seconds);
    };

    const playTone = (freq: number, seconds: number, gain: number, type: OscillatorType = "sine"): void => {
        const c = ensure();
        if (!c) {
            return;
        }
        const t = c.currentTime;
        const osc = c.createOscillator();
        osc.type = type;
        osc.frequency.setValueAtTime(freq, t);
        const g = c.createGain();
        g.gain.setValueAtTime(gain, t);
        g.gain.exponentialRampToValueAtTime(0.001, t + seconds);
        osc.connect(g);
        g.connect(c.destination);
        osc.start(t);
        osc.stop(t + seconds);
    };

    return {
        unlock(): void {
            ensure();
        },
        gunshot(): void {
            playNoise(0.15, 3000, 200, 0.4);
        },
        hit(): void {
            playTone(880, 0.08, 0.25);
        },
        thud(): void {
            playNoise(0.25, 500, 60, 0.5);
            playTone(90, 0.2, 0.3);
        },
        damage(): void {
            playTone(220, 0.15, 0.3, "sawtooth");
        },
    };
}

