// Scene 252: Quake-style FPS — destructible noise terrain (tile removal), shooting,
// navmesh bots, GPU-text HUD, Web Audio SFX. Built purely on the public Lite API:
// character controllers, physics raycasts, navmesh crowds, thin instances, text layers.

import HavokPhysics from "@babylonjs/havok";
import {
    addAgent,
    agentGoto,
    addToScene,
    createBox,
    createCapsule,
    createDefaultTextData,
    createEngine,
