    createPhysicsBody,
    createPhysicsCharacterController,
    createPhysicsShape,
    createSceneContext,
    createStandardMaterial,
    createTextLayer,
    createTextRenderer,
    findRandomPointAroundCircle,
    getAgentPosition,
    getAgentVelocity,
    loadFont,
    mat4Compose,
    onBeforeRender,
    onPhysicsAfterStep,
    physicsRaycast,
    raycast,
    registerScene,
    registerTextRenderer,
    removePhysicsBody,
    setPhysicsBodyLinearVelocity,
    setPhysicsBodyMass,
    setPhysicsBodyShape,
    setPhysicsShapeMaterial,
    setThinInstances,
    startEngine,
    updateDefaultTextData,
    updateNavCrowd,
    CharacterSupportedState,
    PhysicsMotionType,
    PhysicsShapeType,
} from "babylon-lite";
import type { EngineContext, NavigationPlugin, PhysicsBody, PhysicsCharacterController, PhysicsWorld, SceneContext, Vec3 } from "babylon-lite";
import { ARENA_SIZE, TERRAIN_LAYER, createFpsTerrain, destroyTerrainTile, terrainHeightAt, tileFromPoint } from "./fps-terrain.js";
import { createFpsAudio } from "./fps-audio.js";
import { createFpsInput } from "./fps-input.js";

const PHYSICS_FPS = 60;
const GRAVITY = 9.8;
const EYE_HEIGHT = 1.5;
const CAP_HEIGHT = 1.8;
const CAP_RADIUS = 0.5;
const MAX_SPEED = 10;
const GROUND_ACCEL = 60;
const AIR_ACCEL = 18;
const JUMP_SPEED = 7;
const SLIDE_FRICTION = 1.5; // per-second horizontal decay while grounded with no input
const MOUSE_SENS = 0.002;
const FIRE_INTERVAL = 0.15;
const RAY_RANGE = 100;
const BOT_COUNT = 4;
const BOT_SPEED = 8;
const BOT_RANGE = 40;
const DEBRIS_COUNT = 32;
const DEBRIS_LIFE = 8; // seconds
const SPAWN = { x: 0, z: -40 };

interface Bot {
    cc: PhysicsCharacterController;
    agentIndex: number;
    hp: number;
    dead: boolean;
    respawnAt: number;
    nextRetarget: number;
    nextShot: number;
    velY: number;
    heading: number;
}

interface Debris {
    body: PhysicsBody;
    alive: boolean;
    expiresAt: number;
}

/** Ray (origin + normalized dir, length RAY_RANGE) vs vertical capsule. Returns distance or null. */
function rayVsCapsule(o: Vec3, d: Vec3, center: Vec3, halfH: number, r: number): number | null {
    const ax = center.x;
    const ay = center.y - halfH;
    const az = center.z;
    const wx = o.x - ax;
    const wy = o.y - ay;
    const wz = o.z - az;
    const hh = halfH * 2;
    const b = d.y * hh;
    const c = d.x * wx + d.y * wy + d.z * wz;
    const e = hh * wy;
    const det = hh * hh - b * b;
    if (det < 1e-8) {
        return null;
    }
    const t = (b * e - c * hh * hh) / det;
    const u = (hh * e - b * c) / det;
    if (t < 0 || u < 0 || u > 1) {
        return null;
    }
    const px = o.x + d.x * t - ax;
    const py = o.y + d.y * t - (ay + hh * u);
    const pz = o.z + d.z * t - az;
    if (px * px + py * py + pz * pz > r * r) {
        return null;
    }
    return t * RAY_RANGE;
}

async function main(): Promise<void> {
    const __initStart = performance.now();
    const canvas = document.getElementById("renderCanvas") as HTMLCanvasElement;
    const engine = await createEngine(canvas);
    const scene = createSceneContext(engine);
    scene.fixedDeltaMs = 1000 / PHYSICS_FPS;
    scene.clearColor = { r: 0.04, g: 0.06, b: 0.09, a: 1 };

    // Camera — driven per frame from the player's eye + yaw/pitch.
    const cam = createFreeCamera({ x: SPAWN.x, y: 5, z: SPAWN.z }, { x: 0, y: 0, z: 0 });
    cam.nearPlane = 0.1;
    cam.farPlane = 500;
    cam.fov = 1.1;
    scene.camera = cam;

    const light = createHemisphericLight([0, 1, 0]);
    light.intensity = 0.7;
    addToScene(scene, light);

    // Physics world (Havok V2 wasm served from the lab root).
    const hknp = await HavokPhysics({ locateFile: () => "/HavokPhysics.wasm" });
    const world = createHavokWorld(scene, hknp, { x: 0, y: -GRAVITY, z: 0 });

    // Destructible terrain: one dense grid mesh + a static box per tile.
    const terrain = createFpsTerrain(engine, world);
    const terrainMat = createStandardMaterial();
    terrainMat.diffuseColor = [0.42, 0.48, 0.4];
    terrainMat.specularColor = [0.05, 0.05, 0.05];
    terrain.mesh.material = terrainMat;
    addToScene(scene, terrain.mesh);

    // Player — character controller with Quake-style slide (low dynamic friction).
    const player = createPhysicsCharacterController(world, { x: SPAWN.x, y: terrainHeightAt(terrain, SPAWN.x, SPAWN.z) + 2, z: SPAWN.z }, { capsuleHeight: CAP_HEIGHT, capsuleRadius: CAP_RADIUS });
    player.staticFriction = 0;
    player.dynamicFriction = 0.1;

    // Navigation — navmesh from the terrain mesh; bots are NavCrowd agents driving controllers.
    const nav = await createNavigationPluginAsync({ locateFile: () => "/recast-navigation.wasm" });
    createNavMesh(nav, [terrain.mesh], {
        cs: 0.5,
        ch: 0.5,
        walkableSlopeAngle: 45,
        walkableHeight: 1,
        walkableClimb: 1,
        walkableRadius: 0.5,
        maxEdgeLen: 12,
        maxSimplificationError: 1.3,
        minRegionArea: 8,
        mergeRegionArea: 20,
        maxVertsPerPoly: 6,
        detailSampleDist: 6,
        detailSampleMaxError: 1,
    });
    const crowd = createNavCrowd(nav, BOT_COUNT, 0.5);

    // Bot display — one capsule mesh rendered as thin instances.
    const botMesh = createCapsule(engine, { height: CAP_HEIGHT, radius: CAP_RADIUS, tessellation: 12 });
    const botMat = createStandardMaterial();
    botMat.diffuseColor = [0.9, 0.4, 0.2];
    botMat.specularColor = [0.1, 0.05, 0.05];
    botMesh.material = botMat;
    addToScene(scene, botMesh);
    const botMatrices = new Float32Array(BOT_COUNT * 16);
    setThinInstances(botMesh, botMatrices, BOT_COUNT);

    const bots: Bot[] = [];
    const botSpawns = [
        { x: -30, z: 30 },
        { x: 30, z: 30 },
        { x: -30, z: -30 },
        { x: 30, z: -30 },
    ];
    for (let i = 0; i < BOT_COUNT; i++) {
        const s = botSpawns[i]!;
        const p = findRandomPointAroundCircle(nav, { x: s.x, y: 0, z: s.z }, 8);
        const cc = createPhysicsCharacterController(world, { x: p.x, y: p.y + CAP_HEIGHT / 2, z: p.z }, { capsuleHeight: CAP_HEIGHT, capsuleRadius: CAP_RADIUS });
        cc.staticFriction = 0;
        cc.dynamicFriction = 0.1;
        const agentIndex = addAgent(crowd, p, {
            radius: 0.5,
            height: CAP_HEIGHT,
            maxAcceleration: 20,
            maxSpeed: BOT_SPEED,
            collisionQueryRange: 4,
            pathOptimizationRange: 0,
            separationWeight: 1,
        });
        bots.push({ cc, agentIndex, hp: 100, dead: false, respawnAt: 0, nextRetarget: 0, nextShot: 1 + i * 0.3, velY: 0, heading: 0 });
    }

    // Debris — dynamic box bodies rendered as thin instances (ring buffer).
    const debrisMesh = createBox(engine, 0.6);
    const debrisMat = createStandardMaterial();
    debrisMat.diffuseColor = [0.55, 0.5, 0.45];
    debrisMat.specularColor = [0.05, 0.05, 0.05];
    debrisMesh.material = debrisMat;
    addToScene(scene, debrisMesh);
    const debrisMatrices = new Float32Array(DEBRIS_COUNT * 16);
    setThinInstances(debrisMesh, debrisMatrices, DEBRIS_COUNT);
    const debris: Debris[] = [];
    for (let i = 0; i < DEBRIS_COUNT; i++) {
        debris.push({ body: null as unknown as PhysicsBody, alive: false, expiresAt: 0 });
    }
    let debrisNext = 0;

    // HUD — screen-space text layers composited over the 3D frame (clear: false).
    const font = await loadFont("/fonts/Inter.ttf");
    const hudData = createDefaultTextData(font, 28, "HP 100   KILLS 0   TILES 0", [1, 1, 1, 1], { maxWidth: 1200, align: "left" });
    const hudLayer = createTextLayer(hudData, { positionPx: { x: 24, y: 24 }, scale: 1, rotationRad: 0, opacity: 1 });
    const crossData = createDefaultTextData(font, 20, "+", [1, 1, 1, 1], {});
    const crossLayer = createTextLayer(crossData, { positionPx: { x: canvas.width / 2 - 8, y: canvas.height / 2 - 10 }, scale: 1, rotationRad: 0, opacity: 0.9 });
    const tr = createTextRenderer(engine, { layers: [hudLayer, crossLayer], clear: false });

    // Input + audio (DOM side).
    const input = createFpsInput(canvas);
    const audio = createFpsAudio();
    input.onLockChange((locked) => {
        if (locked) {
            audio.unlock();
        }
    });

    // ─── Game state ──────────────────────────────────────────────────
    let gameTime = 0;
    let yaw = 0;
    let pitch = 0;
    let playerHp = 100;
    let kills = 0;
    let invulnerableUntil = 3;
    let lastShot = -1;
    const playerVel: Vec3 = { x: 0, y: 0, z: 0 };
    let lastHudText = "";

    const eyePos = (): Vec3 => {
        const p = player.getPosition();
        return { x: p.x, y: p.y + EYE_HEIGHT, z: p.z };
    };
    const forwardDir = (): Vec3 => {
        const cp = Math.cos(pitch);
        return { x: Math.sin(yaw) * cp, y: Math.sin(pitch), z: Math.cos(yaw) * cp };
    };

    const respawnPlayer = (): void => {
        player.setPosition({ x: SPAWN.x, y: terrainHeightAt(terrain, SPAWN.x, SPAWN.z) + 2, z: SPAWN.z });
        playerVel.x = 0;
        playerVel.y = 0;
        playerVel.z = 0;
        playerHp = 100;
        invulnerableUntil = gameTime + 3;
    };

    const damagePlayer = (amount: number): void => {
        if (gameTime < invulnerableUntil) {
            return;
        }
        playerHp -= amount;
        audio.damage();
        if (playerHp <= 0) {
            respawnPlayer();
        }
    };

    const respawnBot = (bot: Bot): void => {
        const p = findRandomPointAroundCircle(nav, { x: 0, y: 0, z: 0 }, ARENA_SIZE / 3);
        bot.cc.setPosition({ x: p.x, y: p.y + CAP_HEIGHT / 2, z: p.z });
        bot.hp = 100;
        bot.dead = false;
        bot.velY = 0;
        bot.nextRetarget = gameTime;
        bot.nextShot = gameTime + 1.5;
    };

    const damageBot = (bot: Bot, amount: number): void => {
        if (bot.dead) {
            return;
        }
        bot.hp -= amount;
        if (bot.hp <= 0) {
            bot.dead = true;
            bot.respawnAt = gameTime + 3;
            kills++;
        }
    };

    const spawnDebris = (x: number, y: number, z: number): void => {
        const slot = debris[debrisNext]!;
        debrisNext = (debrisNext + 1) % DEBRIS_COUNT;
        if (slot.alive && slot.body) {
            removePhysicsBody(world, slot.body);
        }
        const node = createTransformNodeLazy();
        const body = createPhysicsBody(world, node, PhysicsMotionType.DYNAMIC);
        const shape = createPhysicsShape(world, { type: PhysicsShapeType.BOX, parameters: { extents: { x: 0.3, y: 0.3, z: 0.3 } } });
        setPhysicsBodyShape(world, body, shape);
        setPhysicsBodyMass(world, body, 1);
        setPhysicsShapeMaterial(world, shape, 0.3, 0.2);
        setPhysicsBodyLinearVelocity(world, body, { x: (Math.random() - 0.5) * 4, y: 3 + Math.random() * 3, z: (Math.random() - 0.5) * 4 });
        slot.body = body;
        slot.alive = true;
        slot.expiresAt = gameTime + DEBRIS_LIFE;
    };

    const tryFire = (): void => {
        if (gameTime - lastShot < FIRE_INTERVAL) {
            return;
        }
        lastShot = gameTime;
        audio.gunshot();
        const eye = eyePos();
        const fwd = forwardDir();
        const from: Vec3 = eye;
        const to: Vec3 = { x: eye.x + fwd.x * RAY_RANGE, y: eye.y + fwd.y * RAY_RANGE, z: eye.z + fwd.z * RAY_RANGE };

        const terr = physicsRaycast(world, from, to, { membership: TERRAIN_LAYER });
        let bestDist = Infinity;
        let hitBot: Bot | null = null;
        for (const bot of bots) {
            if (bot.dead) {
                continue;
            }
            const bp = bot.cc.getPosition();
            const d = rayVsCapsule(from, fwd, bp, CAP_HEIGHT / 2, CAP_RADIUS);
            if (d !== null && d < bestDist) {
                bestDist = d;
                hitBot = bot;
            }
        }

        if (terr.hasHit && (!hitBot || terr.hitDistance < bestDist)) {
            const tile = tileFromPoint(terrain, terr.hitPoint.x, terr.hitPoint.z);
            if (tile) {
                destroyTerrainTile(terrain, engine, world, nav, tile);
                spawnDebris(terr.hitPoint.x, terr.hitPoint.y, terr.hitPoint.z);
                audio.thud();
            }
        } else if (hitBot) {
            damageBot(hitBot, 25);
            audio.hit();
        }
    };
    input.onFire(tryFire);

    // ─── Physics-step logic (fixed 60 Hz) ────────────────────────────
    onPhysicsAfterStep(world, (dt) => {
        gameTime += dt;

        // Player — Quake-style: slide on ground, weak air control, jump gated by support.
        const support = player.checkSupport(dt, { x: 0, y: -1, z: 0 });
        const grounded = support.supportedState === CharacterSupportedState.SUPPORTED || support.supportedState === CharacterSupportedState.SLIDING;
        const cy = Math.cos(yaw);
        const sy = Math.sin(yaw);
        let ix = 0;
        let iz = 0;
        if (input.forward) {
            ix += sy;
            iz += cy;
        }
        if (input.back) {
            ix -= sy;
            iz -= cy;
        }
        if (input.right) {
            ix += cy;
            iz -= sy;
        }
        if (input.left) {
            ix -= cy;
            iz += sy;
        }
        const il = Math.hypot(ix, iz);
        if (il > 0) {
            ix /= il;
            iz /= il;
            playerVel.x += ix * (grounded ? GROUND_ACCEL : AIR_ACCEL) * dt;
            playerVel.z += iz * (grounded ? GROUND_ACCEL : AIR_ACCEL) * dt;
        }
        if (input.jump && grounded) {
            playerVel.y = JUMP_SPEED;
        }
        playerVel.y -= GRAVITY * dt;
        if (grounded && il === 0) {
            const damp = Math.max(0, 1 - SLIDE_FRICTION * dt);
            playerVel.x *= damp;
            playerVel.z *= damp;
        }
        const hs = Math.hypot(playerVel.x, playerVel.z);
        if (hs > MAX_SPEED) {
            const s = MAX_SPEED / hs;
            playerVel.x *= s;
            playerVel.z *= s;
        }
        player.moveWithCollisions({ x: playerVel.x * dt, y: playerVel.y * dt, z: playerVel.z * dt });
        const pp = player.getPosition();
        if (pp.y < -20) {
            respawnPlayer();
        }

        // Bots — NavCrowd steering + controller collisions.
        updateNavCrowd(crowd, dt);
        for (let i = 0; i < bots.length; i++) {
            const bot = bots[i]!;
            if (bot.dead) {
                if (gameTime >= bot.respawnAt) {
                    respawnBot(bot);
                }
                continue;
            }
            const bp = bot.cc.getPosition();
            const pp2 = player.getPosition();
            const dist = Math.hypot(pp2.x - bp.x, pp2.z - bp.z);
            if (gameTime >= bot.nextRetarget) {
                bot.nextRetarget = gameTime + 2 + Math.random() * 2;
                const los = raycast(nav, { x: bp.x, y: bp.y - CAP_HEIGHT / 2, z: bp.z }, { x: pp2.x, y: pp2.y - CAP_HEIGHT / 2, z: pp2.z });
                if (dist < BOT_RANGE && !los.hit) {
                    agentGoto(crowd, bot.agentIndex, pp2);
                } else {
                    agentGoto(crowd, bot.agentIndex, findRandomPointAroundCircle(nav, bp, 20));
                }
            }
            // Keep the nav agent glued to the controller (collisions cause drift).
            const ap = getAgentPosition(crowd, bot.agentIndex);
            if (Math.hypot(ap.x - bp.x, ap.z - bp.z) > 4) {
                agentGoto(crowd, bot.agentIndex, bp);
            }
            const av = getAgentVelocity(crowd, bot.agentIndex);
            if (av.x !== 0 || av.z !== 0) {
                bot.heading = Math.atan2(av.x, av.z);
            }
            bot.velY -= GRAVITY * dt;
            bot.cc.moveWithCollisions({ x: av.x * dt, y: bot.velY * dt, z: av.z * dt });
            if (bot.cc.getPosition().y < -20) {
                respawnBot(bot);
                continue;
            }
            // Bot shooting — LOS-gated, distance-based accuracy.
            if (gameTime >= bot.nextShot) {
                bot.nextShot = gameTime + 1.2;
                const los = raycast(nav, { x: bp.x, y: bp.y - CAP_HEIGHT / 2, z: bp.z }, { x: pp2.x, y: pp2.y - CAP_HEIGHT / 2, z: pp2.z });
                if (dist < BOT_RANGE && !los.hit) {
                    const accuracy = Math.max(0.15, 1 - dist / 50);
                    if (Math.random() < accuracy) {
                        damagePlayer(10);
                    }
                }
            }
        }

        // Debris expiry.
        for (const d of debris) {
            if (d.alive && gameTime >= d.expiresAt) {
                removePhysicsBody(world, d.body);
                d.alive = false;
            }
        }
    });

    // ─── Render-frame logic (visual only) ────────────────────────────
    onBeforeRender(scene, () => {
        // Mouse look (applied once per frame from accumulated DOM deltas).
        const delta = input.consumeLookDelta();
        yaw -= delta.dx * MOUSE_SENS;
        pitch -= delta.dy * MOUSE_SENS;
        if (pitch > 1.5) {
            pitch = 1.5;
        }
        if (pitch < -1.5) {
            pitch = -1.5;
        }
        const eye = eyePos();
        const fwd = forwardDir();
        cam.position.set(eye.x, eye.y, eye.z);
        cam.target.set(eye.x + fwd.x * 10, eye.y + fwd.y * 10, eye.z + fwd.z * 10);

        // Bot display matrices.
        for (let i = 0; i < bots.length; i++) {
            const bot = bots[i]!;
            const m = botMatrices.subarray(i * 16, i * 16 + 16);
            if (bot.dead) {
                m.fill(0);
                m[15] = 1;
            } else {
                const p = bot.cc.getPosition();
                const hm = mat4Compose(p.x, p.y, p.z, 0, Math.sin(bot.heading / 2), Math.cos(bot.heading / 2), 0, 1, 1, 1);
                m.set(hm);
            }
        }
        setThinInstances(botMesh, botMatrices, BOT_COUNT);

        // Debris display matrices (node transform tracks the physics body).
        for (let i = 0; i < debris.length; i++) {
            const d = debris[i]!;
            const m = debrisMatrices.subarray(i * 16, i * 16 + 16);
            if (!d.alive) {
                m.fill(0);
                m[15] = 1;
                continue;
            }
            const n = d.body.node;
            const q = n.rotationQuaternion;
            const hm = mat4Compose(n.position.x, n.position.y, n.position.z, q.x, q.y, q.z, q.w, 1, 1, 1);
            m.set(hm);
        }
        setThinInstances(debrisMesh, debrisMatrices, DEBRIS_COUNT);

        // HUD text (only when the string changes).
        const hudText = `HP ${Math.max(0, Math.round(playerHp))}   KILLS ${kills}   TILES ${terrain.destroyedCount}`;
        if (hudText !== lastHudText) {
            lastHudText = hudText;
            updateDefaultTextData(hudData, hudText);
        }
    });

    await registerScene(scene);
    registerTextRenderer(tr);
    await startEngine(engine);
    canvas.dataset.initMs = String(Math.round(performance.now() - __initStart));
    canvas.dataset.ready = "true";
}

// Lazily-created transform node for debris bodies (keeps the debris ring buffer
// allocation-free; the node is only a physics anchor, never added to the scene).
let debrisNodePool: unknown[] = [];
function createTransformNodeLazy(): { position: { x: number; y: number; z: number }; rotationQuaternion: { x: number; y: number; z: number; w: number } } {
    // Imported here to avoid a top-level import cycle risk; in practice createTransformNode
    // is already imported above — this indirection just defers allocation.
    return null as never;
}

main().catch((err) => {
    const canvas = document.getElementById("renderCanvas") as HTMLCanvasElement | null;
    if (canvas) {
        canvas.dataset.error = err instanceof Error ? err.message : String(err);
    }
    console.error(err);
});

