const { chromium } = require("playwright");

(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const errors = [];
    page.on("console", (msg) => {
        if (msg.type() === "error") {
            errors.push(msg.text());
        }
    });
    page.on("pageerror", (err) => errors.push(String(err)));
    const t0 = Date.now();
    await page.goto("http://localhost:5182/lite/scene252.html", { waitUntil: "load" });
    const result = await page
        .waitForFunction(
            () => {
                const c = document.getElementById("renderCanvas");
                return c && (c.dataset.ready || c.dataset.error) ? { ready: c.dataset.ready, error: c.dataset.error, initMs: c.dataset.initMs } : null;
            },
            null,
            { timeout: 90000, polling: 500 }
        )
        .then((h) => h.jsonValue())
        .catch(() => null);
    console.log(JSON.stringify({ result, ms: Date.now() - t0, errors: errors.slice(0, 12) }, null, 2));
    await browser.close();
})().catch((e) => {
    console.error(e);
    process.exit(1);
});

