/** Ray (origin + normalized dir, clamped to RAY_RANGE) vs a vertical capsule. Returns distance or null. */
function rayVsCapsule(o: Vec3, d: Vec3, center: Vec3, halfH: number, r: number): number | null {
    const ax = center.x;
    const ay = center.y - halfH; // bottom cap center
    const az = center.z;
    const hh = halfH * 2;
    const wx = o.x - ax;
    const wy = o.y - ay;
    const wz = o.z - az;
    const b = d.y * hh;
    const c = d.x * wx + d.y * wy + d.z * wz;
    const e = hh * wy;
    const det = hh * hh - b * b;
    let best: number | null = null;
    // Cylindrical band (axis between the two caps).
    if (det > 1e-8) {
        const t = (b * e - c * hh * hh) / det;
        const u = (e - b * c) / det;
        if (t >= 0 && t <= RAY_RANGE && u >= 0 && u <= 1) {
            const px = o.x + d.x * t - ax;
            const py = o.y + d.y * t - (ay + hh * u);
            const pz = o.z + d.z * t - az;
            if (px * px + py * py + pz * pz <= r * r) {
                best = t;
            }
        }
    }
    // End caps, treated as spheres.
    const cap = (cy: number): number | null => {
        const qx = o.x - ax;
        const qy = o.y - cy;
        const qz = o.z - az;
        const t = -(d.x * qx + d.y * qy + d.z * qz);
        if (t < 0 || t > RAY_RANGE) {
            return null;
        }
        const px = o.x + d.x * t - ax;
        const py = o.y + d.y * t - cy;
        const pz = o.z + d.z * t - az;
        if (px * px + py * py + pz * pz <= r * r) {
            return t;
        }
        return null;
    };
    const tb = cap(ay);
    if (tb !== null && (best === null || tb < best)) {
        best = tb;
    }
    const tt = cap(ay + hh);
    if (tt !== null && (best === null || tt < best)) {
        best = tt;
    }
    return best;
}

