/**
 * Serve @recast-navigation dist files raw, bypassing Vite's dev transform.
 * Vite dev appends an inline base64 source map to every served module; for the
 * 560 KB recast glue that bloats the response to ~2 MB, which the lab's
 * constrained test browser cannot finish within its per-page load window (the
 * module import never settles — no rejection, just a stall, on every page).
 * The three dist files (core, generators, wasm glue) are self-contained native
 * ESM with no imports to rewrite, so raw bytes are a drop-in replacement.
 */
function serveRecastRawPlugin(): Plugin {
    return {
        name: "serve-recast-raw",
        configureServer(server) {
            server.middlewares.use((req, res, next) => {
                const url = (req.url ?? "").split("?")[0];
                if (!url.startsWith("/@fs/") || !url.includes("/@recast-navigation/")) {
                    next();
                    return;
                }
                const fsPath = url.slice("/@fs/".length);
                readFile(fsPath, (err, data) => {
                    if (err) {
                        next();
                        return;
                    }
                    res.statusCode = 200;
                    res.setHeader("Content-Type", "text/javascript; charset=utf-8");
                    res.setHeader("Cache-Control", "no-cache");
                    res.end(data);
                });
            });
        },
    };
}

